package com.studenthub.controller;import com.studenthub.dao.PrivateMessageDAO;import com.studenthub.util.CsrfToken;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet(name="DeletePrivateConversationServlet",urlPatterns="/messages/delete") public class DeletePrivateConversationServlet extends HttpServlet{private final PrivateMessageDAO dao=new PrivateMessageDAO();@Override protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{if(!CsrfToken.isValid(q)){r.sendError(403);return;}try{dao.hide(Long.parseLong(q.getParameter("conversationId")),(Long)q.getSession().getAttribute("userId"));r.setStatus(204);}catch(SecurityException e){r.sendError(403);}catch(Exception e){r.sendError(400);}}}
